## Plug-and-Play Algorithms

```xiom
pub interface CompressionStrategy {
  fn compress(self: &Self, data: &Vec[Byte]) -> Vec[Byte];
  fn decompress(self: &Self, data: &Vec[Byte]) -> Vec[Byte];
}

pub type GzipCompressor = {};
pub type ZstdCompressor = { level: Int; }
pub type NoCompression = {};

impl CompressionStrategy for GzipCompressor {
  fn compress(self: &GzipCompressor, data: &Vec[Byte]) -> Vec[Byte] {
    return gzip_compress(data);
  }
  fn decompress(self: &GzipCompressor, data: &Vec[Byte]) -> Vec[Byte] {
    return gzip_decompress(data);
  }
}

impl CompressionStrategy for ZstdCompressor {
  fn compress(self: &ZstdCompressor, data: &Vec[Byte]) -> Vec[Byte] {
    return zstd_compress(data, self.level);
  }
  fn decompress(self: &ZstdCompressor, data: &Vec[Byte]) -> Vec[Byte] {
    return zstd_decompress(data);
  }
}

// The context uses the strategy via interface
pub type FileSaver = {
  compressor: Box[dyn CompressionStrategy];
}

impl FileSaver {
  fn save(self: &FileSaver, path: Str, data: &Vec[Byte]) {
    let compressed = self.compressor.compress(data);
    fs.write(path, &compressed);
  }
}

fn main() {
  let saver = FileSaver{ compressor: GzipCompressor{} };
  saver.save("data.bin.gz", &my_data);

  // Swap compression strategy at runtime:
  let saver = FileSaver{ compressor: ZstdCompressor{ level: 3 } };
  saver.save("data.bin.zst", &my_data);
}
```

### Strategy with Closures

```xiom
fn process[T](data: &Vec[T], strategy: fn(&T) -> Bool) -> Vec[T] {
  var result = Vec[T]();
  for item in data {
    if strategy(item) { result.push(item); }
  }
  return result;
}

let evens = process(&nums, |n| n % 2 == 0);
let big = process(&nums, |n| n > 10);
```

### Strategy Selection

```xiom
fn choose_strategy(use_compression: Bool, level: Int) -> Box[dyn CompressionStrategy] {
  if use_compression {
    return Box::new(ZstdCompressor{ level: level });
  }
  return Box::new(NoCompression{});
}
```

