pub interface SortStrategy {
  fn sort(self: &Self, data: &Vec[Int]) -> Vec[Int];
}

pub type AscendingSort = {};
pub type DescendingSort = {};

impl SortStrategy for AscendingSort {
  fn sort(self: &AscendingSort, data: &Vec[Int]) -> Vec[Int] {
    let mut result = data.clone();
    result.sort();
    return result;
  }
}

impl SortStrategy for DescendingSort {
  fn sort(self: &DescendingSort, data: &Vec[Int]) -> Vec[Int] {
    let mut result = data.clone();
    result.sort();
    result.reverse();
    return result;
  }
}

fn main() -> Int {
  let v = Vec[Int]();
  v.push(3); v.push(1); v.push(4); v.push(1); v.push(5);
  let strategy = AscendingSort{};
  let sorted = strategy.sort(&v);
  return sorted[0];
}
